from dataclasses import dataclass
from typing import Dict, List, Tuple

@dataclass(frozen=True)
class Tagged:
    side: str
    value: str

def complementary_orbits(n: int) -> List[Tuple[Tagged, Tagged]]:
    if n < 0:
        raise ValueError("n must be nonnegative")
    return [(Tagged("original", f"a{i}"), Tagged("complement", f"c{i}"))
            for i in range(n)]

if __name__ == "__main__":
    for n in range(6):
        orbits = complementary_orbits(n)
        assert len(orbits) == n
        assert 2 * len(orbits) % 2 == 0
        print(n, 2 * n, len(orbits))

